// Offline build: pinned vendor files are committed; no package install is needed.
const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '../static');
const read = name => fs.readFileSync(path.join(root, name), 'utf8');
const inlineSafe = source => source.replace(/<\/script/gi, '<\\/script');
const withoutSourceMap = source => source.replace(/^\/\/# sourceMappingURL=.*$/gm, '');
const engine = [
  '// Generated by scripts/build_terminal_assets.cjs. Do not edit this bundle.',
  '// xterm.js 6.0.0 / addon-fit 0.11.0 (MIT); licenses: static/vendor/*/LICENSE.',
  withoutSourceMap(read('vendor/xterm/lib/xterm.js')),
  withoutSourceMap(read('vendor/addon-fit/lib/addon-fit.js')),
  `(() => { const css = document.createElement('style'); css.textContent = ${
    JSON.stringify(read('vendor/xterm/css/xterm.css'))
  }; document.head.appendChild(css); })();`,
  read('terminal-input.js'),
  read('fallback-input.js'),
  read('terminal-view.js'),
].join('\n;\n');
fs.writeFileSync(path.join(root, 'terminal-engine.js'), inlineSafe(engine).trimEnd() + '\n');
fs.writeFileSync(
  path.join(root, 'native-panel.js'),
  inlineSafe(engine + '\n;\n' + read('panel-socket.js') + '\n;\n' + read('native-panel-client.js')).trimEnd() + '\n',
);
console.log('Built terminal-engine.js and the self-contained native-panel.js');
